def checked(value, data_type):
    if value is None or data_type == "any": return value
    if data_type == "boolean": return value if isinstance(value, bool) else None
    if data_type == "number": return value if isinstance(value, (int, float)) and not isinstance(value, bool) else None
    if data_type == "string": return value if isinstance(value, str) else None
    return None

def tri_and(*v):
    return False if any(x is False for x in v) else True if v and all(x is True for x in v) else None

def tri_or(*v):
    return True if any(x is True for x in v) else False if v and all(x is False for x in v) else None

def tri_not(v):
    return None if not isinstance(v, bool) else not v

def tri_xor(*v):
    return None if not v or any(not isinstance(x, bool) for x in v) else sum(x is True for x in v) % 2 == 1

def tri_nand(*v):
    return tri_not(tri_and(*v))

def tri_nor(*v):
    return tri_not(tri_or(*v))

def tri_xnor(*v):
    return tri_not(tri_xor(*v))

